inputs = ['ab', 'fj', 'bzgy', 'xhxfax', 'hvuju']
outputs = ['yfhb', 'fkff', 'bkfcjay', 'xhxfyfhx', 'hvukffu']

# Let's look at character-level differences
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\nPair {i}: '{inp}' -> '{outp}'")

    # Find positions where characters differ
    diff_positions = []
    for j, (char_in, char_out) in enumerate(zip(inp, outp)):
        if char_in != char_out:
            diff_positions.append((j, char_in, char_out))

    if len(inp) != len(outp):
        # Handle length differences
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append((j, inp[j], outp[j]))
        # Add remaining characters
        if len(inp) > len(outp):
            for j in range(min_len, len(inp)):
                diff_positions.append((j, inp[j], None))
        elif len(outp) > len(inp):
            for j in range(min_len, len(outp)):
                diff_positions.append((j, None, outp[j]))

    print(f"  Differences at positions: {diff_positions}")

